      "category": "embedding_representation",
      "rationale": "Increase tied item embedding width from 48 to 64 across all four category models. Existing hidden_units plumbing resizes the matching convolution channels, saves the width in metadata, and reconstructs matching predictor shapes. Preserve features, topology, scoring, loss, optimizer and one checkpoint per category.",
      "edits": [
        {
          "find": "HIDDEN_UNITS  = int(os.environ.get(\"NEXTITNET_HIDDEN\", \"48\"))",
          "replace": "HIDDEN_UNITS  = int(os.environ.get(\"NEXTITNET_HIDDEN\", \"64\"))"
        }
      ]
    }
  ],
  "change_summary": "Increase tied embedding and matching hidden width to 64; existing metadata-backed predictor construction maintains checkpoint compatibility."
}
